featured.description:
App data only: never trust roots, runtime loader, Worker/SQL callbacks, keys,
bearer, or authority ports. Existing registered application ID stays exact;
logical declaration identity is not an inferred CP registration receipt.

featured.signature:
type MdbasePhase = 
/** The SDK is starting: show the app's wordmark or the cached list. */
{
    readonly kind: "starting";
}
/** Not signed in. `notice` explains why when sign-in just ended (window closed, signed out). */
 | {
    readonly kind: "signed_out";
    readonly notice: MdbaseProblem | null;
}
/** Waiting for the Connect window: sign in, add a collection or approve one. */
 | {
    readonly kind: "authorizing";
    readonly purpose: "sign_in" | "add" | "approve";
    readonly collectionId: string | null;
}
/** Signed in, nothing open: choose from `snapshot.collections` or add one. */
 | {
    readonly kind: "choosing";
    readonly lastApproval: MdbaseApprovalOutcome | null;
}
/** SDK-9: `slow` turns on when opening takes longer than usual. */
 | {
    readonly kind: "opening";
    readonly collectionId: string;
    readonly displayName: string | null;
    readonly slow: boolean;
    readonly progress?: import("../app-host/opening-progress.js").AppOpeningProgress | null;
}
/** The requested collection is not approved for this app (yet). */
 | {
    readonly kind: "needs_approval";
    readonly collectionId: string;
    readonly displayName: string | null;
    readonly declined: boolean;
}
/** Open, but needs a one-time setup: `setup.plan()` then `setup.apply(plan)`. */
 | {
    readonly kind: "needs_setup";
    readonly collectionId: string;
    readonly collection: MdbaseCollectionSummary;
}
/** Open and usable. `rechecking` and `problem` are informational only. */
 | {
    readonly kind: "ready";
    readonly collectionId: string;
    readonly collection: MdbaseCollectionSummary;
    readonly connection: MdbaseApplicationConnection;
    readonly rechecking: boolean;
    readonly problem: MdbaseProblem | null;
    readonly unavailableTypes: readonly MdbaseUnavailableType[];
}
/** Working before connecting (`createMdbase(declaration, {unsynced: true})`):
 * the app's unsynced collection is open. Use `connection` as when ready.
 * Its work is saved only in this browser: say so, and offer "Connect to sync
 * your work". It is never in `snapshot.collections`. */
 | {
    readonly kind: "unsynced";
    readonly collectionId: string;
    readonly connection: MdbaseApplicationConnection;
    readonly rechecking: boolean;
}
/** Can't continue: show `problem` with its action. */
 | {
    readonly kind: "problem";
    readonly collectionId: string | null;
    readonly problem: MdbaseProblem;
}
/** The SDK can't run here (SSR, Node, an unsupported browser). */
 | {
    readonly kind: "unavailable";
    readonly problem: MdbaseProblem;
} | {
    readonly kind: "closed";
};

type MdbaseAccessResult = {
    readonly status: "granted";
    readonly actions: readonly FileAction[];
} | {
    readonly status: "declined";
} | {
    readonly status: "cancelled";
};

type Query = {
    types?: string[];
    where?: string;
    order_by?: PlainValue;
    select?: PlainValue;
    limit?: number;
    cursor?: string;
    timezone?: string;
    context?: PlainValue;
    [key: string]: PlainValue | undefined;
};
